/// <summary>
/// CB625_TMSSOPickingListExtraction, Sales order extraction
/// </summary>
[METTMSEngineExecutionModeAttribute(METTMSEngineExecutionMode::SalesOrderPickingList)]
internal final class METTMSEngineSalesOrderProccess_PickingList extends METTMSEngineOrderProccess
{
    boolean     isInternalCrossDockOrder;
    boolean     isCSDWarehouse;
    WMSPickingRouteID   pickingRouteId;
    METSalesTable   metSalesTable;
}

Method.Source:
/// <summary>
/// initialize default parameters and variables
/// </summary>
/// <param name = "_salesTable">SalesTable record</param>
protected void init(METTMSSourceRecordHeaderMap _sourceRecord)
{
    super(_sourceRecord);

    metSalesTable = _sourceRecord.getExtensionTable();

    isInternalCrossDockOrder    = metSalesTable.InternalCrossDockOrder;
    isCSDWarehouse  = inventLocation.METCSDWarehouse;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public METStagingLaneId getStagingLaneId()
{
    METStagingLaneId ret = metSalesTable.StagingLaneId;

    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
protected METRouteStopIdentifier getRouteStopIdentifier()
{
    METRouteStopIdentifier ret = metSalesTable.OriginalRouteStopIdentifier;


    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
protected METRouteIdentifier getRouteIdentifier()
{
    METRouteIdentifier ret = metSalesTable.OriginalRouteIdentifier;


    return ret;
}

/// <summary>
/// New method
/// </summary>
/// <param name = "_salesOrderShipmentLoadHeader">SO finalisation shipment load header</param>
/// <param name = "_packingSlipId">Delivery note number</param>
public void new(SalesTable _salesTable, WMSPickingRouteID _pickingRouteId = '')
{
    this.init(_salesTable);

    // Generated pickingListId
    pickingRouteId = _pickingRouteId;
}

/// <summary>
/// Create an instance of <c>METTMSEngineLinesTmpBuilder</c>
/// </summary>
/// <param name = "_tmsEngineProcess">METTMSEngineSalesOrderProcess enum</param>
/// <param name = "_salesTable"><c>SalesTable</c> record</param>
/// <returns>New instance of <c>METTMSEngineLinesTmpBuilder</c></returns>
METTMSEngineLinesTmpBuilder getTmpBuilderInstance(METTMSEngineExecutionMode _tmsEngineProcess, METTMSSourceRecordHeaderMap _sourceRecord)
{
    return METTMSEngineLinesTmpBuilder::construct(_tmsEngineProcess, _sourceRecord, '', pickingRouteId);
}

/// <summary>
/// Retrieve the METTMSShipmentOrderTable record based on the TMS engine delivery note posting logic
/// </summary>
/// <param name = "_salesId">Sales order number</param>
/// <param name = "_forUpdate">Select record for update</param>
/// <param name = "_pickingRouteId">Picking list number</param>
/// <returns><c>METTMSShipmentOrderTable</c> record found or empty.</returns>
protected METTMSShipmentOrderTable getTMSShipmentOrderTable(str _orderId, boolean _forUpdate = false, WMSPickingRouteID _pickingRouteId = '')
{
    METTMSShipmentOrderTable TMSShipmentOrderTable;

    // check to see if there is a TSO with Order number = SalesOrderID, and Pick List ID = PickListID that this order is being added to
    TMSShipmentOrderTable = super(_orderId, _forUpdate, pickingRouteId);

    if (!TMSShipmentOrderTable)
    {
        TMSShipmentOrderTable = METTMSShipmentOrderTable::findByOrder(_orderId);
    }
    return TMSShipmentOrderTable;
}

/// <summary>
/// Method to set the fields for <c>METTMSShipmentOrderTable</c> record
/// </summary>
/// <param name = "_tmsShipmentOrderTable"><c>METTMSShipmentOrderTable</c> record</param>
protected void setTMSShipmentOrderFields(METTMSShipmentOrderTable _tmsShipmentOrderTable)
{
    super(_tmsShipmentOrderTable);

    // Step 3d: Create TSO record
    // As this is an order not processed by “TMS Engine” in past, create a TSO record to capture details of this order similar to
    // what was defined in “Step 3d” of the CB624 FSD, with the following differences an extra Pick List ID field as defined in the table below.
    _tmsShipmentOrderTable.PickListId = pickingRouteId;

}

/// <summary>
/// error message
/// </summary>
/// <returns>error txt</returns>
protected ErrorTxt errorMessage()
{
    if(isInternalCrossDockOrder)
    {
        return strFmt("@MET:TMSEngineSalesOrderProccessPickingListError", "@MET:xDockSalesTableFieldGroupName", sourceRecord.OrderId);
    }
    else
    if (isCSDWarehouse)
    {
        return strFmt("@MET:TMSEngineSalesOrderProccessPickingListError", "@MET:CSDOrder", sourceRecord.OrderId);
    }
    else
    {
        return strFmt("@MET:TMSEngineSalesOrderProcessCreation", sourceRecord.OrderId);
    }
}

/// <summary>
/// Initialise temporary table with calculations
/// </summary>
void initTmpTable()
{
    METTMSEngineLinesTmpBuilder tmpBuilder = this.getTmpBuilderInstance(METTMSEngineExecutionMode::SalesOrderPickingList, sourceRecord);
    proccessLinesTmp = tmpBuilder.populateTmpTable();
}
